CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), email varchar(320) NOT NULL, password_hash text NOT NULL, role varchar(30) NOT NULL DEFAULT 'customer' CHECK (role IN ('customer','merchant_admin','staff')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id,email), UNIQUE (tenant_id,id));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), sku varchar(80) NOT NULL, name varchar(200) NOT NULL, description text, price numeric(12,2) NOT NULL CHECK(price >= 0), stock_qty integer NOT NULL DEFAULT 0 CHECK(stock_qty >= 0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,sku), UNIQUE(tenant_id,id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), customer_id uuid NOT NULL, status varchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','fulfilled','cancelled')), total_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(total_amount >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,customer_id) REFERENCES app_users(tenant_id,id), UNIQUE(tenant_id,id));
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), order_id uuid NOT NULL, product_id uuid NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), unit_price numeric(12,2) NOT NULL CHECK(unit_price >= 0), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id), UNIQUE(order_id,product_id));
CREATE TABLE audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), table_name text NOT NULL, record_id uuid NOT NULL, operation varchar(10) NOT NULL CHECK(operation IN ('INSERT','UPDATE','DELETE')), changed_at timestamptz NOT NULL DEFAULT now(), changed_by text, old_row jsonb, new_row jsonb);
